import React, { useContext, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import GameClient from '../services/GameClient';
import { GameClientContext } from '../contexts/GameClientContext';
import {
    AppPage,
    EmptyState,
    GameRules,
    HeroTopRow,
    Input,
    InputGroup,
    Label,
    LoginForm,
    MetaPill,
    MetaRow,
    PageDescription,
    PageEyebrow,
    PageGrid,
    PageHeadingGroup,
    PageHero,
    PagePanel,
    PageShell,
    PageTitle,
    PanelDescription,
    PanelHeader,
    PanelTitle,
    Rule,
    RulesList,
    RulesTitle,
    SectionLabel,
    SubmitButton,
    SupportingText
} from '../components/GameStyles';

const LoginGrid = styled(PageGrid)`
    grid-template-columns: repeat(12, minmax(0, 1fr));
`;

const LoginPanel = styled(PagePanel)`
    grid-column: span 7;

    @media (max-width: 900px) {
        grid-column: auto;
    }
`;

const GuidePanel = styled(PagePanel)`
    grid-column: span 5;

    @media (max-width: 900px) {
        grid-column: auto;
    }
`;

const LoginPage = () => {
    const { setGameClient } = useContext(GameClientContext);
    const navigate = useNavigate();
    const [playerName, setPlayerName] = useState('');

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!playerName.trim()) {
            alert("Player name cannot be empty");
            return 
        }

        const client = new GameClient(playerName);
        try{
            await client.addPlayer(playerName);
            setGameClient(client);
            console.log("LoginPage Player: ", client.getPlayerName());

            navigate('/mode-selection');
        } catch (error) {
            if (error instanceof Error) {
                alert(error.message);
            } else {
                console.error('Unexpected error:', error);
                alert("Unexpected error");
            }
        }

    };

    return (
        <AppPage>
            <PageShell>
                <PageHero>
                    <HeroTopRow>
                        <PageEyebrow>24 Points Game</PageEyebrow>
                        <MetaPill>Solo and multiplayer</MetaPill>
                    </HeroTopRow>
                    <PageHeadingGroup>
                        <PageTitle>Combine four numbers and reach 24.</PageTitle>
                        <PageDescription>
                            Start with a player name, then choose whether you want a quick
                            solo round or a multiplayer room.
                        </PageDescription>
                    </PageHeadingGroup>
                    <MetaRow>
                        <MetaPill>Use all four numbers exactly once</MetaPill>
                        <MetaPill>+, -, *, / and parentheses</MetaPill>
                    </MetaRow>
                </PageHero>

                <LoginGrid>
                    <LoginPanel>
                        <PanelHeader>
                            <SectionLabel>Step 1</SectionLabel>
                            <PanelTitle>Pick a player name</PanelTitle>
                            <PanelDescription>
                                This name follows you into the next screen and appears in
                                multiplayer rooms.
                            </PanelDescription>
                        </PanelHeader>

                        <LoginForm onSubmit={handleLogin}>
                            <InputGroup>
                                <Label htmlFor="player-name">Player name</Label>
                                <Input
                                    id="player-name"
                                    value={playerName}
                                    onChange={(e) => setPlayerName(e.target.value)}
                                    placeholder="Enter a player name"
                                    required
                                />
                            </InputGroup>
                            <SubmitButton type="submit">
                                Continue to game modes
                            </SubmitButton>
                        </LoginForm>

                        <SupportingText>
                            Next, you&apos;ll choose single-player practice or join the
                            multiplayer room list.
                        </SupportingText>
                    </LoginPanel>

                    <GuidePanel>
                        <GameRules>
                            <RulesTitle>How each round works</RulesTitle>
                            <RulesList>
                                <Rule>Use all four numbers exactly one time.</Rule>
                                <Rule>Combine them with arithmetic and parentheses.</Rule>
                                <Rule>Keep adjusting your formula until the result is 24.</Rule>
                                <Rule>Play alone for practice or compete in shared rooms.</Rule>
                            </RulesList>
                        </GameRules>

                        <EmptyState>
                            <SectionLabel>What happens next</SectionLabel>
                            <PanelTitle>Choose your path</PanelTitle>
                            <SupportingText>
                                Single-player starts a room for just you. Multiplayer takes you
                                to the room list so you can create a room or join one that is
                                already open.
                            </SupportingText>
                        </EmptyState>
                    </GuidePanel>
                </LoginGrid>
            </PageShell>
        </AppPage>
    );
};

export default LoginPage;
